extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve caricarsi senza errori"):
		return
	var player := find_by_name(main, "Player") as CharacterBody2D
	if not check("player", player != null, "La scena deve contenere un CharacterBody2D chiamato Player"):
		return
	var touching_before = get_prop(player, "is_touching_wall", null)
	if not check("prop_exists", touching_before != null, "Lo script del Player deve definire la variabile is_touching_wall"):
		return
	var wall := StaticBody2D.new()
	wall.position = Vector2(420, 400)
	var col := CollisionShape2D.new()
	var box := RectangleShape2D.new()
	box.size = Vector2(20, 100)
	col.shape = box
	wall.add_child(col)
	main.add_child(wall)
	player.position = Vector2(400, 400)
	await hold_action("move_right", 10)
	var touching_after = get_prop(player, "is_touching_wall", false)
	check("wall_detected", touching_after == true, "Quando il personaggio spinge contro un muro, is_touching_wall deve diventare true (invece è %s)" % str(touching_after))

